1	%% Constants and environment
2	
3	%#ok<*NBRAK>
4	dataBaseDir = 'D:\temp\exercise_data_release';
5	
6	% This file has *only* data during exercises, already separated out by exercise.  
7	% The "singleonly" in the filename means that it only contains "single-activity" traces.
8	% So this is useful for the "which exercise?" (recognition) and counting problems, not for 
9	% the "when is there exercise?" problem.
10	dataFileSingleActivity = fullfile(dataBaseDir,'exercise_data.50.0000_singleonly.mat');
11	
12	% This file has data from complete exercise sessions, so it includes lots of time
13	% where there's no execise happening.  The "multionly" in the filename means that it 
14	% only contains "multi-activity" traces.  So this is useful for the "when are you 
15	% exercising?"  problem (segmentation).
16	dataFileMultiActivity = fullfile(dataBaseDir,'exercise_data.50.0000_multionly.mat');
17	
18	% We separate these into two files to make it a little easier to work on
19	% one problem or the other.  You can completely reconstruct the
20	% "single-activity" file *from* the "multi-activity" file, because it also
21	% includes all the times at which each exercise started and stopped.
22	
23	% In this file, we're going to play around with data from a particular 
24	% subject doing a particular exercise.  Not every subject did every
25	% exercise; I'm picking a combination that I happen to know isn't empty.
26	% In fact I'm also picking a subject that I happen to know participated 
27	% more than once.
28	iSubject = 52;
29	exerciseName = 'Two-arm Dumbbell Curl (both arms, not alternating)';
30	
31	
32	%% Load data... this will take a couple minutes; it's about 2.5GB
33	
34	fprintf(1,'Loading single-activity data...\n');
35	exerciseDataSingleActivity = load(dataFileSingleActivity);
36	
37	fprintf(1,'Loading multi-activity data...\n');
38	exerciseDataMultiActivity = load(dataFileMultiActivity);
39	
40	fprintf(1,'Finished loading data\n');
41	
42	% Both of these files have similar formats format... the data lives in a cell
43	% matrix called "subject_data", where each row is a subject, and each column
44	% is a type of exercise.  
45	%
46	% In the "multi-activity" data, there's only one column, since we haven't separated
47	% data out into exercises yet.
48	
49	% The column names for the single-activity data are here:
50	activities = exerciseDataSingleActivity.exerciseConstants.activities';
51	nActivityTypes = length(activities);
52	
53	% Sanity-check our data matrices
54	assert(nActivityTypes == size(exerciseDataSingleActivity.subject_data,2));
55	
56	assert(1 == size(exerciseDataMultiActivity.subject_data,2));
57	
58	% Both files should have the same number of subjects
59	nParticipants = size(exerciseDataSingleActivity.subject_data,1);
60	assert(nParticipants == size(exerciseDataMultiActivity.subject_data,1));
61	
62	
63	%% Find the column for a particular exercise we want to look at
64	
65	exerciseIndex = find(strcmp(exerciseDataSingleActivity.exerciseConstants.activities,...
66	    exerciseName));
67	
68	
69	%% This matrix has one row per person, one column per exercise
70	
71	% Any given cell in "subject_data" is a struct array, with one element for
72	% each time that subject (this row) performed that exercise (this column)
73	%
74	% So for example, the following cell contains a struct array, with one element per 
75	% record, of every time this subject came in to our lab and did the exercise we picked 
76	% above, which may span multiple visits.
77	recordings = exerciseDataSingleActivity.subject_data{iSubject,exerciseIndex};
78	
79	% How many times did this subject do this particular exercise?
80	nRecordings = length(recordings);
81	
82	
83	%% Now let's look at one instance of this particular subject doing this particular exercise
84	
85	% Arbitrarily grab the first instance to plot
86	recording = recordings(1);
87	assert(strcmp(recording.activityName,exerciseName));
88	
89	% Plot the raw accelerometer and gyro data (at 50Hz)
90	accelT = recording.data.accelDataMatrix(:,1);
91	accelXYZ = recording.data.accelDataMatrix(:,[2:4]);
92	gyroT = recording.data.gyroDataMatrix(:,1);
93	gyroXYZ = recording.data.gyroDataMatrix(:,[2:4]);
94	
95	subplot(2,1,1);
96	plot(accelT,accelXYZ);
97	xlabel('Time (seconds)');
98	ylabel('Accelerometer output (g)');
99	legend({'X','Y','Z'});
100	
101	subplot(2,1,2);
102	plot(gyroT,gyroXYZ);
103	xlabel('Time (seconds)');
104	ylabel('Gyro output (dps)');
105	legend({'X','Y','Z'});
106	
107	
108	%% Now let's play around with the multi-activity data
109	
110	% Remember, in this file, we haven't separated out the periods of exercise
111	% and non-exercise, everything is one big long trace per subject, with
112	% labels to tell us where exercises started and stopped.
113	
114	recordings = exerciseDataMultiActivity.subject_data{iSubject,1};
115	
116	% Each instance here represents a visit to our lab
117	nVisits = length(recordings);
118	
119	% Arbitrarily grab the first visit
120	recording = recordings(1);
121	
122	% This is a cell matrix that tells us when exercises started and stopped,
123	% and how many repetitions the subject did for each exercise.  The columns 
124	% are:
125	%
126	% [exercise name],[start time],[end time],[notes],[number of repetitions]
127	
128	% So let's plot this subject's accelerometer data (just one axis, so the plot
129	% doesn't get too complex), with vertical lines to indicate where exercises
130	% started, with labels for each exercise.
131	nActivities = size(recording.activityStartMatrix,1);
132	
133	accelT = recording.data.accelDataMatrix(:,1);
134	accelZ = recording.data.accelDataMatrix(:,4);
135	
136	plot(accelT,accelZ);
137	hold on;
138	xlabel('Time (seconds)');
139	ylabel('Accelerometer output (g)');
140	
141	for(iActivity=1:nActivities)
142	    activityName = recording.activityStartMatrix{iActivity,1};
143	    if (strcmpi(activityName,'non-exercise'))
144	        continue;
145	    end
146	    activityCount = recording.activityStartMatrix{iActivity,5};
147	    activityStartTime = recording.activityStartMatrix{iActivity,2};
148	    activityEndTime = recording.activityStartMatrix{iActivity,3};
149	    lineHandle = line([activityStartTime activityStartTime],[-0.5 0.5]);
150	    lineHandle.Color = [0 1 0];
151	    lineHandle = line([activityEndTime activityEndTime],[-0.5 0.5]);
152	    lineHandle.Color = [1 0 0];
153	    yValue = -0.5 + rand();
154	    tHandle = text(activityStartTime,yValue,sprintf('%s x %d',activityName,activityCount));    
155	    tHandle.Rotation = 45;
156	end % ...for each activity
157	
158	hold off; zoom on;
159	xlim([100 300])
